import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

function isWin() { return process.platform === 'win32'; }

function pidsOnPort(port) {
  if (!port) return [];
  if (!isWin()) {
    const r = spawnSync('sh', ['-lc', `lsof -ti tcp:${Number(port)} 2>/dev/null || true`], { encoding: 'utf8' });
    return [...new Set((r.stdout || '').split(/\s+/).map(x => Number(x)).filter(Boolean))];
  }
  const r = spawnSync('netstat', ['-ano', '-p', 'TCP'], { encoding: 'utf8' });
  const pids = [];
  const portRe = new RegExp(`:${Number(port)}\\s+`, 'i');
  for (const line of (r.stdout || '').split(/\r?\n/)) {
    if (!/LISTENING/i.test(line)) continue;
    if (!portRe.test(line)) continue;
    const m = line.trim().match(/(\d+)$/);
    if (m) pids.push(Number(m[1]));
  }
  return [...new Set(pids)];
}

function killPid(pid) {
  if (!pid) return { pid, skipped: true };
  if (isWin()) {
    const r = spawnSync('taskkill', ['/PID', String(pid), '/T', '/F'], { encoding: 'utf8' });
    return { pid, status: r.status, stdout: r.stdout, stderr: r.stderr, ok: r.status === 0 || /not found|没有找到|不存在/i.test(r.stderr || r.stdout || '') };
  }
  const r = spawnSync('kill', ['-TERM', String(pid)], { encoding: 'utf8' });
  return { pid, status: r.status, stdout: r.stdout, stderr: r.stderr, ok: r.status === 0 };
}

export async function run(input = {}) {
  const projectRoot = input.projectRoot || 'E:\\quant-framework';
  const stateFile = path.join(projectRoot, '.conexus', 'alphalab-runner', 'state.json');
  let state = {};
  if (fs.existsSync(stateFile)) state = JSON.parse(fs.readFileSync(stateFile, 'utf8'));
  const backendPort = Number(input.backendPort || state.backendPort || 8000);
  const frontendPort = Number(input.frontendPort || state.frontendPort || 5173);
  const pidSet = new Set([
    state.frontendPid,
    state.backendPid,
    ...(Array.isArray(state.frontendPids) ? state.frontendPids : []),
    ...(Array.isArray(state.backendPids) ? state.backendPids : []),
    ...pidsOnPort(frontendPort),
    ...pidsOnPort(backendPort),
  ].map(Number).filter(Boolean));
  const stopped = [...pidSet].map(killPid);
  const ok = stopped.every(x => x.skipped || x.ok);
  let archivedStateFile = stateFile;
  if (fs.existsSync(stateFile)) {
    archivedStateFile = stateFile.replace(/\.json$/, `.stopped.${Date.now()}.json`);
    fs.renameSync(stateFile, archivedStateFile);
  }
  return { ok, stopped, stateFile: archivedStateFile, ports: { backendPort, frontendPort }, message: ok ? 'Stopped AlphaLab services recorded on configured ports.' : 'Some processes may not have stopped; inspect result.' };
}
